from topics_a import t, T
V='surveyor'
t('surveyor',V,'a surveyor',"Surveyors inspect, measure and value property and land, report on condition, advise on building work and help resolve disputes.",["Choose the right type of surveyor for the job.","RICS membership gives assurance.","Ask what the report includes."])
t('chartered-surveyor',V,'a chartered surveyor',"Chartered surveyors are RICS members (MRICS or FRICS) who have passed professional assessment and follow RICS standards.",["Check the RICS directory.","Chartered status covers many specialisms.","Ask about relevant experience."])
t('building-surveyor',V,'a building surveyor',"Building surveyors assess building condition, design and manage repairs and refurbishments, and advise on defects and regulations.",["Useful for older or altered buildings.","They can manage building projects.","Ask about dilapidations experience."])
t('building-survey-surveyor',V,'a surveyor for a building survey',"A building survey (RICS Level 3) is the most detailed inspection of a property's condition, suited to older, larger or altered homes.",["Best for period and unusual properties.","Reports explain defects and repairs.","Book before exchange."])
t('homebuyer-surveyor',V,'a HomeBuyer surveyor',"HomeBuyer surveys (RICS Level 2) inspect conventional homes in reasonable condition, flagging urgent issues and often including a valuation.",["Suits modern homes in good condition.","Check whether a valuation is included.","Follow up concerns before exchange."])
t('property-surveyor',V,'a property surveyor',"Property surveyors provide surveys, valuations and advice for buyers, owners, landlords and lenders.",["Match report type to the property.","Independent advice protects buyers.","Ask about follow-up calls."])
t('commercial-surveyor',V,'a commercial surveyor',"Commercial surveyors advise on business property: lettings, rent reviews, lease renewals, valuations, rates and acquisitions.",["Rent reviews follow lease terms.","Business rates can be challenged.","Market knowledge matters."])
t('commercial-building-surveyor',V,'a commercial building surveyor',"Commercial building surveyors carry out pre-acquisition surveys, schedules of condition and dilapidations for business premises.",["Schedules of condition protect tenants.","Defects affect negotiations.","Plan before signing leases."])
t('party-wall-surveyor',V,'a party wall surveyor',"Party wall surveyors deal with notices and awards under the Party Wall etc. Act 1996 when work affects shared walls, boundaries or nearby foundations.",["Notices must be served before work starts.","Neighbours can agree a single surveyor.","Awards protect both sides."])
t('boundary-surveyor',V,'a boundary surveyor',"Boundary surveyors investigate where legal boundaries lie, using title plans, deeds and measured surveys, and act as experts in disputes.",["Land Registry plans show general boundaries.","Disputes can be costly; get early advice.","Measured surveys provide evidence."])
t('land-surveyor',V,'a land surveyor',"Land surveyors produce topographical and measured surveys of land for design, planning and development.",["Accurate surveys underpin design.","Ask about drone and laser scanning.","Check deliverable formats."])
t('measured-surveyor',V,'a measured building surveyor',"Measured surveyors produce accurate floor plans, elevations and sections of existing buildings, often for architects.",["Architects need accurate existing drawings.","Laser scanning speeds up surveys.","Agree the level of detail."])
t('quantity-surveyor',V,'a quantity surveyor',"Quantity surveyors estimate and control construction costs, prepare tender documents and manage contract payments and variations.",["Early cost advice prevents overspend.","They help compare builders' tenders.","Useful for disputes over final accounts."])
t('project-management-surveyor',V,'a project management surveyor',"Project management surveyors run building projects on your behalf, managing contractors, programme, quality and budget.",["Clear contracts reduce risk.","Regular site meetings keep control.","Agree reporting frequency."])
t('damp-surveyor',V,'a damp surveyor',"Independent damp surveyors diagnose the true cause of damp, such as condensation, leaks or rising damp, before you pay for treatment.",["Independent surveys avoid sales-led diagnoses.","Condensation is a common cause.","Look for PCA qualifications."])
t('defect-surveyor',V,'a defect surveyor',"Defect surveyors investigate specific problems such as cracks, leaks and structural movement, and recommend repairs.",["Targeted inspections save time.","Structural engineers may be needed.","Insurers may need reports."])
t('asbestos-surveyor',V,'an asbestos surveyor',"Asbestos surveyors carry out management or refurbishment and demolition surveys to find asbestos before work or for duty holders.",["Refurbishment surveys are needed before works.","Use UKAS-accredited organisations.","Non-domestic duty holders must manage asbestos."])
t('dilapidations-surveyor',V,'a dilapidations surveyor',"Dilapidations surveyors advise landlords and tenants on repair obligations at the end of a lease and negotiate claims.",["Schedules of condition at the start help tenants.","Claims follow a pre-action protocol.","Negotiation often settles claims."])
t('leasehold-surveyor',V,'a leasehold surveyor',"Leasehold surveyors value lease extensions and freehold purchases, and advise on service charges.",["Lease length affects valuation.","Marriage value has been subject to reform.","Statutory processes have deadlines."])
t('insurance-valuation-surveyor',V,'an insurance valuation surveyor',"Insurance valuation surveyors calculate the reinstatement cost of rebuilding a property for buildings insurance.",["Under-insurance can reduce claims.","Rebuild cost differs from market value.","Review valuations periodically."])
# consultants
K='consultant'
t('business-consultant',K,'a business consultant',"Business consultants help owners improve strategy, operations, finance and growth, often with a fresh outside view.",["Agree measurable goals.","Short diagnostic projects can be a good start.","Make sure knowledge stays with you."])
t('management-consultant',K,'a management consultant',"Management consultants help organisations solve problems, improve performance and deliver change, from strategy to operations.",["Clear scope prevents drift.","Look for sector experience.","Agree governance and reporting."])
t('compliance-consultant',K,'a compliance consultant',"Compliance consultants help businesses meet regulatory requirements, write policies, train staff and prepare for audits.",["Identify which regulations apply.","Policies must match practice.","Regular reviews matter."],hub='compliance-consultants')
t('regulatory-compliance-consultant',K,'a regulatory compliance consultant',"Regulatory compliance consultants support firms regulated by bodies such as the FCA, CQC or ICO with authorisations, monitoring and remediation.",["Check experience with your regulator.","Consultants do not replace your accountable people.","Keep records of decisions."],hub='compliance-consultants')
t('hr-consultant',K,'an HR consultant',"HR consultants advise on policies, contracts, recruitment, performance, disciplinaries, restructures and employee relations.",["CIPD membership shows training.","Get employment law advice for high-risk issues.","Handbooks should match practice."],hub='hr-consultants')
t('it-consultant',K,'an IT consultant',"IT consultants advise on systems, cloud migration, cyber security, networks and technology strategy for businesses.",["Cyber Essentials can be a good baseline.","Document systems and access.","Plan support after projects."],hub='it-consultants')
t('education-consultant','education','an education consultant',"Education consultants help families choose schools, prepare applications and navigate admissions, special educational needs and university choices.",["Start early.","Know application deadlines.","Ask for local knowledge."])
t('school-admissions-consultant','education','a school admissions consultant',"School admissions consultants help with applications, oversubscription criteria and appeals for state and independent schools.",["Understand each school's criteria.","Appeals have fixed timetables.","Evidence supports your case."])
t('planning-consultant','planning','a planning consultant',"Planning consultants advise on planning policy, prepare applications and appeals, and negotiate with councils for homeowners and developers.",["Pre-application advice reduces risk.","Local plan policies are key.","Appeals have deadlines."])
R='recruitment'
t('recruitment-agency',R,'a recruitment agency',"Recruitment agencies find, screen and introduce candidates for permanent, temporary and contract roles.",["Specialist agencies know their markets.","Agree terms before receiving CVs.","Give clear briefs."])
t('recruitment-consultant',R,'a recruitment consultant',"Recruitment consultants manage hiring for employers and support candidates, from briefing to offer and onboarding.",["A good consultant challenges your brief.","Ask for market salary data.","Agree communication rhythm."])
t('employment-agency',R,'an employment agency',"Employment agencies help people find work and help employers fill temporary and permanent roles.",["Job seekers generally should not be charged.","Temporary workers have rights.","Check right-to-work processes."])
t('graduate-recruitment-agency',R,'a graduate recruitment agency',"Graduate recruitment agencies connect employers with graduates and school leavers for schemes and entry-level roles.",["Timing follows the academic calendar.","Assessment centres help select.","Offer structured development."])
t('it-recruitment-agency',R,'an IT recruitment agency',"IT recruitment agencies source developers, engineers, analysts and security specialists for permanent and contract roles.",["Technical screening matters.","Contract roles may raise IR35 questions.","Salary expectations move quickly."])
# care / funeral / notary
t('care-advisor','care','a care adviser',"Care advisers help families understand care options, funding and assessments, and find suitable home care or care homes.",["Ask for a council needs assessment.","Visit homes before deciding.","Get funding advice early."])
t('care-home-advisor','care','a care home adviser',"Care home advisers help families compare homes, understand contracts and fees, and plan a move.",["Check CQC ratings.","Read contracts carefully.","Ask about fee increases."])
t('elderly-care-advisor','care','an elderly care adviser',"Elderly care advisers support older people and families with care at home, residential options, funding and benefits.",["Attendance Allowance may be available.","Home adaptations can help.","Plan powers of attorney."])
t('funeral-director','funeral','a funeral director',"Funeral directors care for the person who has died, guide families through arrangements and organise the funeral.",["Ask for the standardised price list.","Direct cremation is an option.","Check membership of NAFD or SAIF."])
t('funeral-plan-advisor','funeral','a funeral plan adviser',"Funeral plan advisers help you compare pre-paid funeral plans, which must be sold by FCA-authorised providers.",["Check FCA authorisation.","Understand what is covered.","Check cancellation terms."])
t('notary','notary','a notary public',"Notaries public authenticate documents, witness signatures and prepare papers for use abroad, including apostilles.",["Check the destination country's requirements.","Bring original ID.","Allow time for legalisation."])
